begin;
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); admin_id uuid:=gen_random_uuid(); item record; value jsonb; plan uuid; denied boolean; obj text; p jsonb:='{"label":"Opéra Garnier","latitude":48.87194,"longitude":2.33162}'; q jsonb:='{"label":"Gare de Lyon","latitude":48.8449,"longitude":2.3735}';
begin
 for item in select * from(values(a,'passenger'),(b,'passenger'),(d,'driver'),(admin_id,'admin'))t(id,kind) loop
  insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data) values(item.id,'authenticated','authenticated',item.id::text||'@goome.invalid',now(),now(),now(),'{}','{}');
  if item.kind='admin' then insert into goome_private.admin_emails(email) values(item.id::text||'@goome.invalid');end if;
  perform set_config('request.jwt.claim.sub',item.id::text,true);
  perform public.goome_register('Test '||item.kind,case when item.kind='admin' then 'passenger' else item.kind end,'+33600000000');
 end loop;
 perform set_config('request.jwt.claim.sub',a::text,true);
 execute 'set local role authenticated';
 perform public.goome_account_save('favorites',jsonb_build_array(p||'{"name":"Domicile","id":"test"}'));
 perform public.goome_account_save('contacts','[{"id":"contact","name":"Test contact","phone":"+33600000000"}]');
 perform public.goome_account_save('settings','{"arrival":false,"offers":true}');
 perform public.goome_profile_update('Nouveau nom','+33611111111');
 plan:=public.goome_plan_save(p,q,'standard',now()+interval '2 days');
 value:=public.goome_account_data();
 if jsonb_array_length(value->'favorites')<>1 or jsonb_array_length(value->'contacts')<>1 or jsonb_array_length(value->'plans')<>1 or (value->'settings'->>'arrival')::boolean is not false then raise exception 'FAILED: account persistence';end if;
 denied:=false;begin perform public.goome_account_save('favorites','[{"name":"Outside","label":"Invalid","latitude":0,"longitude":0}]');exception when others then denied:=true;end;if not denied then raise exception 'FAILED: invalid address accepted';end if;
 denied:=false;begin perform public.goome_account_save('contacts','[{"name":"Invalid","phone":"x"}]');exception when others then denied:=true;end;if not denied then raise exception 'FAILED: invalid contact accepted';end if;
 denied:=false;begin perform public.goome_plan_save(p,q,'standard',now()-interval '1 day');exception when others then denied:=true;end;if not denied then raise exception 'FAILED: past plan accepted';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',b::text,true);
 execute 'set local role authenticated';
 value:=public.goome_account_data();
 if jsonb_array_length(value->'favorites')<>0 or jsonb_array_length(value->'contacts')<>0 or jsonb_array_length(value->'plans')<>0 then raise exception 'FAILED: cross-account data visibility';end if;
 denied:=false;begin perform public.goome_plan_cancel(plan);exception when others then denied:=true;end;if not denied then raise exception 'FAILED: unrelated plan cancellation';end if;
 denied:=false;begin perform public.goome_document_review(d,'license',true);exception when others then denied:=true;end;if not denied then raise exception 'FAILED: passenger document review';end if;
 execute 'reset role';
 obj:=d::text||'/license/test.pdf';insert into storage.objects(bucket_id,name,owner_id) values('goome-driver-documents',obj,d::text);
 perform set_config('request.jwt.claim.sub',d::text,true);
 execute 'set local role authenticated';
 perform public.goome_document_save('license',obj,'test.pdf');
 value:=public.goome_account_data();if jsonb_array_length(value->'documents')<>1 then raise exception 'FAILED: document registration';end if;
 if not exists(select 1 from storage.objects where bucket_id='goome-driver-documents' and name=obj) then raise exception 'FAILED: owner cannot read document';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';
 if exists(select 1 from storage.objects where bucket_id='goome-driver-documents' and name=obj) then raise exception 'FAILED: document visible across accounts';end if;
 denied:=false;begin perform public.goome_document_save('license',obj,'test.pdf');exception when others then denied:=true;end;if not denied then raise exception 'FAILED: cross-account document registration';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',admin_id::text,true);execute 'set local role authenticated';
 if not exists(select 1 from storage.objects where bucket_id='goome-driver-documents' and name=obj) then raise exception 'FAILED: admin cannot read document';end if;
 perform public.goome_document_review(d,'license',true);
 value:=public.goome_account_data();if not exists(select 1 from jsonb_array_elements(value->'documents') x where x->>'user_id'=d::text and x->>'status'='approved') then raise exception 'FAILED: admin document review';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 perform public.goome_plan_cancel(plan);
 value:=public.goome_account_data();if value->'plans'->0->>'status'<>'cancelled' then raise exception 'FAILED: plan cancellation';end if;
 execute 'reset role';
 if has_function_privilege('anon','public.goome_account_data()','execute') or has_function_privilege('anon','public.goome_document_review(uuid,text,boolean)','execute') then raise exception 'FAILED: anonymous account API';end if;
 if has_table_privilege('authenticated','public.goome_account_settings','update') then raise exception 'FAILED: unchecked settings mutation';end if;
 if (select public from storage.buckets where id='goome-driver-documents') then raise exception 'FAILED: documents are public';end if;
end $$;
rollback;
select 'PASS: settings, favorites, contacts, profile editing, planned rides, private documents, admin review, invalid input rejection, anonymous restrictions and cross-account isolation; all test records rolled back.' as result;
